import json

try:
    with open('hermes_cli/registry/_meta.json') as f:
        meta = json.load(f)

    agents = meta.get('agents', {})
    print(f"\nRegistered agents: {len(agents)}")

    layers = {'Layer A': [], 'Layer B': [], 'Layer C': []}
    for name, config in agents.items():
        layer = config.get('layer', 'Unknown')
        layers[layer].append(name)

    for layer, names in layers.items():
        if names:
            print(f"\n{layer} ({len(names)} agents):")
            for name in sorted(names)[:5]:
                print(f"  • {name}")
            if len(names) > 5:
                print(f"  ... and {len(names) - 5} more")

except FileNotFoundError:
    print("⚠️ Registry not found")
except Exception as e:
    print(f"⚠️ Error reading registry: {e}")

EOF
